#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    int N;
    cin >> N;
    vector<double> cx(N), cy(N);
    for(int i=0;i<N;i++) cin >> cx[i] >> cy[i];

    vector<bool> is_prime(N, false);
    {
        vector<bool> sieve(max(N,2), true);
        sieve[0]=false; if(N>1) sieve[1]=false;
        for(int i=2;(long long)i*i<N;i++)
            if(sieve[i])
                for(int j=i*i;j<N;j+=i) sieve[j]=false;
        for(int i=0;i<N;i++) is_prime[i]=sieve[i];
    }

    auto ddist = [&](int a, int b) -> double {
        double dx=cx[a]-cx[b], dy=cy[a]-cy[b];
        return sqrt(dx*dx+dy*dy);
    };

    // step is 1-indexed: step s uses edge from tour[s-1] to tour[s]
    // penalty if step%10==0 and tour[s-1] is not prime
    auto getmult = [&](int step, int src) -> double {
        return (step%10==0 && !is_prime[src]) ? 1.1 : 1.0;
    };

    auto tourCost = [&](const vector<int>& t) -> double {
        double cost=0;
        for(int s=1;s<=N;s++){
            cost += ddist(t[s-1],t[s]) * getmult(s, t[s-1]);
        }
        return cost;
    };

    // Grid-based NN
    double minx=1e18, maxx=-1e18, miny=1e18, maxy=-1e18;
    for(int i=0;i<N;i++){
        minx=min(minx,cx[i]); maxx=max(maxx,cx[i]);
        miny=min(miny,cy[i]); maxy=max(maxy,cy[i]);
    }

    int gridSize = max(1, (int)sqrt((double)N / 4.0));
    double cellW = (maxx-minx)/gridSize + 1e-9;
    double cellH = (maxy-miny)/gridSize + 1e-9;
    if(cellW < 1e-12) cellW = 1.0;
    if(cellH < 1e-12) cellH = 1.0;

    auto getCellXY = [&](double x, double y) -> pair<int,int> {
        int gx = min(gridSize-1, max(0,(int)((x-minx)/cellW)));
        int gy = min(gridSize-1, max(0,(int)((y-miny)/cellH)));
        return {gx, gy};
    };

    auto buildNNTour = [&](int start) -> vector<int> {
        vector<vector<int>> g(gridSize*gridSize);
        for(int i=0;i<N;i++){
            auto [gx,gy]=getCellXY(cx[i],cy[i]);
            g[gy*gridSize+gx].push_back(i);
        }

        vector<bool> visited(N, false);
        vector<int> t(N+1);
        t[0]=start;
        visited[start]=true;
        {
            auto [gx,gy]=getCellXY(cx[start],cy[start]);
            auto &v=g[gy*gridSize+gx];
            v.erase(find(v.begin(),v.end(),start));
        }

        for(int step=1;step<N;step++){
            int last=t[step-1];
            auto [gx0,gy0]=getCellXY(cx[last],cy[last]);
            int best=-1; double bestD=1e30;

            for(int rad=0;rad<=2*gridSize;rad++){
                if(best!=-1){
                    double minPoss = max(0.0, (double)(rad-1)) * min(cellW,cellH);
                    if(minPoss > bestD*1.5) break;
                }
                for(int dx=-rad;dx<=rad;dx++){
                    for(int dy=-rad;dy<=rad;dy++){
                        if(abs(dx)!=rad && abs(dy)!=rad) continue;
                        int gx=gx0+dx, gy=gy0+dy;
                        if(gx<0||gx>=gridSize||gy<0||gy>=gridSize) continue;
                        auto &v=g[gy*gridSize+gx];
                        for(int id : v){
                            double d=ddist(last,id);
                            double effD = d * getmult(step, last);
                            if(effD<bestD){bestD=effD;best=id;}
                        }
                    }
                }
                if(best!=-1 && rad>0) break;
            }
            t[step]=best;
            visited[best]=true;
            {
                auto [gx,gy]=getCellXY(cx[best],cy[best]);
                auto &v=g[gy*gridSize+gx];
                v.erase(find(v.begin(),v.end(),best));
            }
        }
        t[N]=start;
        return t;
    };

    auto rotateTo0 = [&](vector<int>& t) {
        int zp=-1;
        for(int i=0;i<N;i++) if(t[i]==0){zp=i;break;}
        if(zp==0) return;
        vector<int> rt(N+1);
        for(int i=0;i<N;i++) rt[i]=t[(zp+i)%N];
        rt[N]=0;
        t=rt;
    };

    vector<int> bestTour;
    double bestCost = 1e30;

    {
        vector<int> starts = {0};
        int numStarts = min(N, 20);
        mt19937 rng(42);
        set<int> seen; seen.insert(0);
        while((int)starts.size()<numStarts){
            int s = rng()%N;
            if(!seen.count(s)){seen.insert(s); starts.push_back(s);}
        }

        for(int s : starts){
            if(elapsed()>0.5) break;
            auto t = buildNNTour(s);
            rotateTo0(t);
            double c = tourCost(t);
            if(c < bestCost){bestCost=c; bestTour=t;}
        }
    }

    vector<int> tour = bestTour;
    double curCost = bestCost;

    // 2-opt with proper delta
    auto doTwoOpt = [&](double timeLimit){
        int window = min(N-1, 500);
        if(N<=3000) window = N-1;
        bool improved = true;
        while(improved && elapsed()<timeLimit){
            improved = false;
            for(int i=1;i<N-1 && elapsed()<timeLimit;i++){
                int jmax = min(i+window, N-1);
                for(int j=i+1;j<=jmax;j++){
                    // Reversing segment [i..j]
                    // Affected edges: step i (i-1->i), steps i+1..j (within segment), step j+1 (j->j+1)
                    // After reverse: step i (i-1->old_j), ..., step j+1 (old_i->j+1)
                    // Due to penalty depending on step and source, need to recompute all affected steps

                    int lo = i, hi = min(j+1, N);
                    double oldC=0;
                    for(int s=lo;s<=hi;s++)
                        oldC+=ddist(tour[s-1],tour[s])*getmult(s,tour[s-1]);

                    reverse(tour.begin()+i, tour.begin()+j+1);

                    double newC=0;
                    for(int s=lo;s<=hi;s++)
                        newC+=ddist(tour[s-1],tour[s])*getmult(s,tour[s-1]);

                    if(newC < oldC - 1e-10){
                        curCost += newC - oldC;
                        improved = true;
                    } else {
                        reverse(tour.begin()+i, tour.begin()+j+1);
                    }
                }
            }
        }
    };

    // Small segment 2-opt first
    {
        int window = min(N-1, 20);
        bool improved = true;
        while(improved && elapsed()<1.0){
            improved = false;
            for(int i=1;i<N-1 && elapsed()<1.0;i++){
                int jmax = min(i+window, N-1);
                for(int j=i+1;j<=jmax;j++){
                    int lo = i, hi = min(j+1, N);
                    double oldC=0;
                    for(int s=lo;s<=hi;s++)
                        oldC+=ddist(tour[s-1],tour[s])*getmult(s,tour[s-1]);

                    reverse(tour.begin()+i, tour.begin()+j+1);

                    double newC=0;
                    for(int s=lo;s<=hi;s++)
                        newC+=ddist(tour[s-1],tour[s])*getmult(s,tour[s-1]);

                    if(newC < oldC - 1e-10){
                        curCost += newC - oldC;
                        improved = true;
                    } else {
                        reverse(tour.begin()+i, tour.begin()+j+1);
                    }
                }
            }
        }
    }

    // Or-opt: relocate single city
    {
        bool improved = true;
        while(improved && elapsed()<1.5){
            improved = false;
            for(int i=1;i<N && elapsed()<1.45;i++){
                // Try relocating tour[i] to different positions
                // Remove tour[i]: affects steps i and i+1
                // Insert at position j: affects steps around j

                double bestDelta = -1e-10;
                int bestJ = -1;

                int city = tour[i];
                // Cost of edges currently involving position i
                // step i: tour[i-1]->tour[i], step i+1: tour[i]->tour[i+1]
                double removeOld = ddist(tour[i-1],tour[i])*getmult(i,tour[i-1])
                                 + ddist(tour[i],tour[i+1])*getmult(i+1,tour[i]);
                // After removal, tour[i-1]->tour[i+1] becomes step i (but steps shift)
                // This is complex due to step renumbering. Use swap instead.

                int lo = max(1, i-50), hi2 = min(N-1, i+50);
                for(int j=lo;j<=hi2;j++){
                    if(j==i) continue;
                    int slo = min(i,j), shi = max(i,j);
                    int elo = max(1, slo), ehi = min(shi+1, N);

                    double oldC=0;
                    for(int s=elo;s<=ehi;s++)
                        oldC+=ddist(tour[s-1],tour[s])*getmult(s,tour[s-1]);

                    swap(tour[i],tour[j]);
                    double newC=0;
                    for(int s=elo;s<=ehi;s++)
                        newC+=ddist(tour[s-1],tour[s])*getmult(s,tour[s-1]);

                    double delta = newC-oldC;
                    if(delta < bestDelta){
                        bestDelta = delta;
                        bestJ = j;
                    }
                    swap(tour[i],tour[j]);
                }

                if(bestJ != -1){
                    swap(tour[i], tour[bestJ]);
                    curCost += bestDelta;
                    improved = true;
                }
            }
        }
    }

    // Final 2-opt
    doTwoOpt(1.9);

    // Make sure tour[N] == tour[0]
    tour[N] = tour[0];

    cout << N+1 << "\n";
    for(int i=0;i<=N;i++) cout << tour[i] << "\n";
}
